import{_ as e,o as t,c as s,a4 as i}from"./chunks/framework.BRzJ4ijD.js";const m=JSON.parse('{"title":"多级缓存 (Multi-Level Cache)","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/cache/multilevel.md","filePath":"system-design/cache/multilevel.md","lastUpdated":1788475713000}'),n={name:"system-design/cache/multilevel.md"};function r(l,a,c,o,h,d){return t(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="多级缓存-multi-level-cache" tabindex="-1">多级缓存 (Multi-Level Cache) <a class="header-anchor" href="#多级缓存-multi-level-cache" aria-label="Permalink to &quot;多级缓存 (Multi-Level Cache)&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>实际生产系统几乎不只用一层 cache, 而是<strong>5+ 层 cache 串联</strong>: CPU L1/L2/L3 → OS page cache → 进程内 (Caffeine/Ristretto) → Redis cluster (remote) → CDN edge (Cloudflare/CloudFront) → Origin。 每一层 cache hit 一毫秒以内代价指数降低; 但每 miss 后 代价上一级。 本章梳理 multilevel cache 的常见层, 各 cache layer 性能与特点, ttl / strict-least-recently / random 策略, 主要 cap-trade-off——最终一篇案例: &quot;Twitter fanout on billion line per day 用多大 cache 层&quot;。</p><hr><h2 id="一、缓存金字塔结构" tabindex="-1">一、缓存金字塔结构 <a class="header-anchor" href="#一、缓存金字塔结构" aria-label="Permalink to &quot;一、缓存金字塔结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─ CPU L1/L2/L3 cache (~1-12ns) ── atomic CPU hardware</span></span>
<span class="line"><span>├─ OS Page Cache (Linux readv, mmap) (~100ns-1µs)</span></span>
<span class="line"><span>├─ In-process cache (Caffeine / Ristretto / LRU) (~50ns-500ns)</span></span>
<span class="line"><span>├─ Remote Redis (Redis cluster ~0.5-2ms)</span></span>
<span class="line"><span>├─ Search/Service 全局 cache (Elasticsearch query cache)</span></span>
<span class="line"><span>├─ CDN edge cache (Cloudflare edge POP) (~5-30ms from edge)</span></span>
<span class="line"><span>└─ Origin (database 真实fetch ~5-50ms)</span></span></code></pre></div><p>查一次请求 path:</p><ol><li>CPU 操作进程 in-memory → 加一个值 cache hit ~50ns</li><li>OS page cache buffer → 加几百 ns</li><li>Network round trip 去 remote Redis → 0.5-2ms</li></ol><p>每一层 cache hit 前一层的同形, 代价 ,故障 window (cache 一失效) 影响 数据轮询.</p><hr><h2 id="二、process-internal-cache" tabindex="-1">二、Process-Internal Cache <a class="header-anchor" href="#二、process-internal-cache" aria-label="Permalink to &quot;二、Process-Internal Cache&quot;">​</a></h2><h3 id="caffeine-ristretto" tabindex="-1">Caffeine / Ristretto <a class="header-anchor" href="#caffeine-ristretto" aria-label="Permalink to &quot;Caffeine / Ristretto&quot;">​</a></h3><ul><li>Java Caffeine (Bench 2018): Window-TinyLFU eviction policy + AMQ (启发最优 LRU) 还有命中率 比 LRU 高 29% in traces.</li><li>Ristretto (Go): similar TinyLFU eviction, high concurrent map-based concurrency access native 支撑.</li></ul><h3 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h3><ul><li>API server 缓存最近 hot 文件 / user_dst_data 共享。</li><li>Code-dec lookup (e.g., country list, color tokens) — almost immutable on minor changes.</li><li>Post metrics / 验证 token Blacklist (短期)</li><li>High-availability 计数器 (rate limiter)</li></ul><h3 id="trade-offs" tabindex="-1">Trade-offs <a class="header-anchor" href="#trade-offs" aria-label="Permalink to &quot;Trade-offs&quot;">​</a></h3><ul><li>Cache size 受进程 RAM 限制, single process 不 persistentent. ** process 多副本 迫使 cache 不 fully coherent replicated, 负 cache 是sof consistency**.</li><li>保护 process startup time。 e.g., fresh JVM 启动 cache 大都会 empty, hot load must warm up.</li><li>内 cache size 多 GB (e.g., 4GB CPU-bound serve), 整 heap 4GB cache 包 single holder. («still allow graceful test»).</li></ul><h3 id="eviction-policies" tabindex="-1">Eviction Policies <a class="header-anchor" href="#eviction-policies" aria-label="Permalink to &quot;Eviction Policies&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Policy</th><th>算法</th><th>Use Case</th></tr></thead><tbody><tr><td>LRU</td><td>淘最长时间没访问的</td><td>大多数 case; simple</td></tr><tr><td>LFU (Least Frequently Used)</td><td>access 频率低 out, 小概率 useParamsLruBut disfrSg little futurist.</td><td>longterm stable data feed</td></tr><tr><td>W-TinyLFU (Caffeine default)</td><td>window admission + count-min sketch frequency tracking</td><td>综合最佳 balance, popular access</td></tr><tr><td>ARC (Adaptive Replacement Cache)</td><td>dual LRUs cache demand subtle 动态 lurking</td><td>cache, e redirects</td></tr><tr><td>Random Replacement</td><td>randomly eviction</td><td>Acad, non-cond. Yes actual 留 still奇</td></tr><tr><td>FIFO</td><td>时序 first-in-out</td><td>queue-based (Memcached simple)</td></tr></tbody></table><h3 id="persistent-cache-vs-in-process-only" tabindex="-1">Persistent Cache vs In-process-only <a class="header-anchor" href="#persistent-cache-vs-in-process-only" aria-label="Permalink to &quot;Persistent Cache vs In-process-only&quot;">​</a></h3><p>persistent to disk 留流 SQLite intermediate map from/to serialize— but 是 capable container/useful AWS Memcached Elasticache persistent AOF.</p><hr><h2 id="三、os-page-cache-page-cache-filesystem-cache" tabindex="-1">三、OS Page Cache (Page Cache, Filesystem Cache) <a class="header-anchor" href="#三、os-page-cache-page-cache-filesystem-cache" aria-label="Permalink to &quot;三、OS Page Cache (Page Cache, Filesystem Cache)&quot;">​</a></h2><p>Linux 内核 transparent cache aggressive: every read() / mmap() 在 文件内容在内存 (空闲 RAM) 保留. Subsequent 念重读到 cache.</p><ul><li>DB WAL ddl 生效, page cache 确被部分数据 buffer 上启平台 no fsync.很多时候商业先软件 reference fsync 只保存 WAL. fsync 时 数据 page cache flushed.</li><li>Postgres RAM-based shared_buffers 尽 25% RAM 配. OS page cache 又填 75%, DB cache + OS cache 可叠加 metricsutors 经典是 老陈正常 4 Ghetto cache.</li></ul><h3 id="direct-io-bypass" tabindex="-1">Direct IO bypass <a class="header-anchor" href="#direct-io-bypass" aria-label="Permalink to &quot;Direct IO bypass&quot;">​</a></h3><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">open</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(path, O_DIRECT </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> O_SYNC);</span></span></code></pre></div><p>PostgreSQL 9.6+ supports cheap. 用 O_DIRECT 与 raw I/O ok DB cache table magic no OS drive.(Buffer Pool).</p><p>InnoDB <code>innodb_flush_method=O_DIRECT</code> 绕 page cache.</p><hr><h2 id="四、redis-cluster-remote-cache" tabindex="-1">四、Redis Cluster (Remote Cache) <a class="header-anchor" href="#四、redis-cluster-remote-cache" aria-label="Permalink to &quot;四、Redis Cluster (Remote Cache)&quot;">​</a></h2><h3 id="single-redis-vs-redis-cluster" tabindex="-1">Single Redis vs Redis Cluster <a class="header-anchor" href="#single-redis-vs-redis-cluster" aria-label="Permalink to &quot;Single Redis vs Redis Cluster&quot;">​</a></h3><ul><li><strong>Standalone</strong>: 单实例, RDB/AOF persistence, replication async to slave 主备</li><li><strong>Sentinel</strong>: 复 sentinel fa over</li><li><strong>Cluster (3.0+)</strong>: 自动 sharding 用 consistent hashing + Redis hash slots (0-16383) for hash-ring distribute. Multi-AZ HA: each hash slot 主 + N replicas.</li></ul><h3 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>client → route hash_slot = CRC16(key) % 16384 → which node primary</span></span>
<span class="line"><span>node forward lightweight (MOVED/ASK redirection)</span></span>
<span class="line"><span>minimum cluster = 3 nodes (3-primary + 3-replica)</span></span></code></pre></div><p>Redis cluster 6 nodes 起 = 3 primary + 3 replica, 自动 fail-over (gossip protocol within cluster).</p><h3 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h3><ul><li>单实例 100K+ QPS (单 thread, 6.0 IO threads allowed)</li><li>Cluster horizontally scales, but cluster routing adds ~1ms for first MOVED operations.</li><li>Sub-millisecond typical合理 hit ratio high.</li></ul><h3 id="weaknesses" tabindex="-1">Weaknesses <a class="header-anchor" href="#weaknesses" aria-label="Permalink to &quot;Weaknesses&quot;">​</a></h3><ul><li>集群 failure 窗口 直之 可写入 11 cold client。</li><li>异步复制 (master-ack client), 异 async makes synchronous feel 该 data lost 实现 rare. 5-10 秒 might不住.</li></ul><h3 id="redis-lua-scripting" tabindex="-1">Redis Lua Scripting <a class="header-anchor" href="#redis-lua-scripting" aria-label="Permalink to &quot;Redis Lua Scripting&quot;">​</a></h3><p>Server-side scripting Redis (Lua语言): Atomic 历史&amp;HUSE 的执行</p><ul><li><code>EVAL script keys... args...</code></li><li>原子 commands Lua single answer.</li><li>Common patterns: rate limiter (token bucket), conditional update.</li></ul><hr><h2 id="五、memcached" tabindex="-1">五、Memcached <a class="header-anchor" href="#五、memcached" aria-label="Permalink to &quot;五、Memcached&quot;">​</a></h2><p>相比 Redis, Memcached 多线程 + 性能 throughput 超单 Redis. dedicated.</p><table tabindex="0"><thead><tr><th>Dimension</th><th>Memcached</th><th>Redis</th></tr></thead><tbody><tr><td>Threads</td><td>Multi-threaded</td><td>Single-threaded (6.0 IO threads)</td></tr><tr><td>Persistence</td><td>NO</td><td>RDB + AOF</td></tr><tr><td>Data structures</td><td>Strings only</td><td>Many (strings, hashes, lists, sets, S-sets)</td></tr><tr><td>Replication</td><td>NO (无 native), 仅 client-side takes</td><td>Master-slave cluster, replication, sentinel</td></tr><tr><td>HA</td><td>Manual (tooling)</td><td>Sentinel + cluster failover aut</td></tr><tr><td>Cluster</td><td>软 via consistent hash client</td><td>cluster protocol native</td></tr><tr><td>Memory</td><td>Slab allocator (no fragmentation)</td><td>jemalloc + eviction</td></tr><tr><td>Latency</td><td>sub-ms</td><td>sub-ms</td></tr><tr><td>Throughput</td><td>multi-threaded version ~1M+ QPS possible</td><td>single node 100K QPS</td></tr></tbody></table><p>Memcached 仍是 Wikimedia, Facebook, Twitter 使用重 cache service because multi-threaded throughput can be ~10x Redis (by Facebook they developed McRouter as client to consistent-hash shard Memcached cluster at scale).</p><hr><h2 id="六、http-cache-cdn" tabindex="-1">六、HTTP Cache / CDN <a class="header-anchor" href="#六、http-cache-cdn" aria-label="Permalink to &quot;六、HTTP Cache / CDN&quot;">​</a></h2><h3 id="cdn-edge-cache" tabindex="-1">CDN Edge Cache <a class="header-anchor" href="#cdn-edge-cache" aria-label="Permalink to &quot;CDN Edge Cache&quot;">​</a></h3><p>Cloudflare / CloudFront / Fastly / Akamai POP 提供 edge POP 缓存 user-facing static content. Latency from POP ~5-30ms depending user distance.</p><h3 id="cache-headers" tabindex="-1">Cache Headers <a class="header-anchor" href="#cache-headers" aria-label="Permalink to &quot;Cache Headers&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cache-Control: max-age=3600, public</span></span>
<span class="line"><span>ETag: &quot;...&quot;</span></span>
<span class="line"><span>Last-Modified: ...</span></span></code></pre></div><ul><li>max-age tells cache TTL.</li><li>public/Private: public = shareable between users; private = browser only.</li><li>ETag 强制条件请求 (<code>If-None-Match → 304 Not Modified</code>).</li></ul><h3 id="ttl-strategy" tabindex="-1">TTL Strategy <a class="header-anchor" href="#ttl-strategy" aria-label="Permalink to &quot;TTL Strategy&quot;">​</a></h3><ul><li>Pure static (logos, fonts): max-age=1 year</li><li>JSON API responses: max-age=60s (eventual)</li><li>HTML page dependent on user: private cache with max-age=0 (revalidate always)</li><li>Web fonts require CORS (cross-origin resource sharing).</li></ul><h3 id="cdn-bypass" tabindex="-1">CDN Bypass <a class="header-anchor" href="#cdn-bypass" aria-label="Permalink to &quot;CDN Bypass&quot;">​</a></h3><p><code>Surrogate-Capability</code> header 让 client 知可 CDN bypass:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cache-Control: no-cache (always revalidate)</span></span>
<span class="line"><span>Cache-Control: no-store (never store)</span></span>
<span class="line"><span>Cache-Control: private (browser only)</span></span></code></pre></div><h3 id="stale-while-revalidate" tabindex="-1">Stale-While-Revalidate <a class="header-anchor" href="#stale-while-revalidate" aria-label="Permalink to &quot;Stale-While-Revalidate&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cache-Control: max-age=600, stale-while-revalidate=86400</span></span></code></pre></div><p>让 cache 在 max-age 过期后 还可 serve stale content 24h, async revalidate.</p><h3 id="cdn-surrogate-control" tabindex="-1">CDN Surrogate-Control <a class="header-anchor" href="#cdn-surrogate-control" aria-label="Permalink to &quot;CDN Surrogate-Control&quot;">​</a></h3><p>Edge-specific cache头:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Surrogate-Control: max-age=86400</span></span>
<span class="line"><span>Surrogate-Key: article-12345</span></span></code></pre></div><p>让 origin invalidate specific edge cache by key (<code>Surrogate-Key: article-12345</code>) without touching user browser cache.</p><h3 id="cloudfront-response-cache-by-path" tabindex="-1">CloudFront Response Cache by Path <a class="header-anchor" href="#cloudfront-response-cache-by-path" aria-label="Permalink to &quot;CloudFront Response Cache by Path&quot;">​</a></h3><p>CloudFront cache by full URL path (path + query string) 可控:</p><ul><li>default: full URL</li><li>multi headers: 防 cache dilution.</li></ul><p>Cloudflare 类似.</p><hr><h2 id="七、cache-hit-ratio-体系" tabindex="-1">七、Cache Hit Ratio 体系 <a class="header-anchor" href="#七、cache-hit-ratio-体系" aria-label="Permalink to &quot;七、Cache Hit Ratio 体系&quot;">​</a></h2><h3 id="计算" tabindex="-1">计算: <a class="header-anchor" href="#计算" aria-label="Permalink to &quot;计算:&quot;">​</a></h3><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>hit_ratio</mtext><mo>=</mo><mfrac><mtext>cache_hits</mtext><mrow><mtext>cache_hits</mtext><mo>+</mo><mtext>cache_misses</mtext></mrow></mfrac></mrow><annotation encoding="application/x-tex">\\text{hit\\_ratio} = \\frac{\\text{cache\\_hits}}{\\text{cache\\_hits} + \\text{cache\\_misses}} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1.0044em;vertical-align:-0.31em;"></span><span class="mord text"><span class="mord">hit_ratio</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:2.3904em;vertical-align:-0.996em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3944em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord">cache_hits</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord text"><span class="mord">cache_misses</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.7em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord">cache_hits</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.996em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><h3 id="trade-off" tabindex="-1">Trade-off: <a class="header-anchor" href="#trade-off" aria-label="Permalink to &quot;Trade-off:&quot;">​</a></h3><ul><li>95% hit ratio 看 seems high; backend load 5% — much less than cache.</li><li>99% hit ratio reduce 99% load to 1% backend load, huge.</li><li>99.9% hit ratio = 0.1% backend = critical services;</li><li>99.99% hit ratio rare, requires extensive cache +精密 TTL + hot-key tuning.</li></ul><h3 id="inverse-formula" tabindex="-1">Inverse formula <a class="header-anchor" href="#inverse-formula" aria-label="Permalink to &quot;Inverse formula&quot;">​</a></h3><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>backend load</mtext><mo>=</mo><mo stretchy="false">(</mo><mn>1</mn><mo>−</mo><mi>h</mi><mi>i</mi><mi>t</mi><mi mathvariant="normal">_</mi><mi>r</mi><mi>a</mi><mi>t</mi><mi>i</mi><mi>o</mi><mo stretchy="false">)</mo><mo>×</mo><mi>t</mi><mi>o</mi><mi>t</mi><mi>a</mi><mi>l</mi><mi mathvariant="normal">_</mi><mi>t</mi><mi>r</mi><mi>a</mi><mi>f</mi><mi>f</mi><mi>i</mi><mi>c</mi></mrow><annotation encoding="application/x-tex">\\text{backend load} = (1 - hit \\_ratio) × total \\_traffic </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord text"><span class="mord">backend load</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1.06em;vertical-align:-0.31em;"></span><span class="mord mathnormal">hi</span><span class="mord mathnormal">t</span><span class="mord" style="margin-right:0.0278em;">_</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mord mathnormal">a</span><span class="mord mathnormal">t</span><span class="mord mathnormal">i</span><span class="mord mathnormal">o</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1.0044em;vertical-align:-0.31em;"></span><span class="mord mathnormal">t</span><span class="mord mathnormal">o</span><span class="mord mathnormal">t</span><span class="mord mathnormal">a</span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mord" style="margin-right:0.0278em;">_</span><span class="mord mathnormal">t</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mord mathnormal">a</span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mord mathnormal">i</span><span class="mord mathnormal">c</span></span></span></span></span></p><p>心 SMELL 测试: backend load 更便宜 theta 性 平台latency I/O, must ensure hit ratio high enough 成 path capacity.</p><hr><h2 id="八、典型-use-cases" tabindex="-1">八、典型 Use Cases <a class="header-anchor" href="#八、典型-use-cases" aria-label="Permalink to &quot;八、典型 Use Cases&quot;">​</a></h2><h3 id="twitter-hot-account-profile" tabindex="-1">Twitter Hot Account Profile <a class="header-anchor" href="#twitter-hot-account-profile" aria-label="Permalink to &quot;Twitter Hot Account Profile&quot;">​</a></h3><p>1M live cache hits / sec cache behind nth latest profile read. 1.5GB working set current active million users (3 KB per profile).</p><h3 id="netflix-open-connect" tabindex="-1">Netflix Open Connect <a class="header-anchor" href="#netflix-open-connect" aria-label="Permalink to &quot;Netflix Open Connect&quot;">​</a></h3><p>视频 content cache at CDN edge. ~100MB movie several CDN POP serve for trending cataloge. Bandth巾 ~ Petabytesserved. Cache edge = (TB per) POP. Origin not touched. CDN provider. 11/9 durability.</p><h3 id="e-commerce-product-page" tabindex="-1">E-Commerce Product Page <a class="header-anchor" href="#e-commerce-product-page" aria-label="Permalink to &quot;E-Commerce Product Page&quot;">​</a></h3><p>For each click, page composed of:</p><ul><li>Product info (redis cache TTL 60s);</li><li>Inventory number (postgres read-through TTL=5s);</li><li>Recommendations (cached batch in 1s + tag queries from storage)</li><li>Reviews cached 60s</li></ul><p>Typical page latency: ~20-50ms from subsystem caches 各 layer.</p><h3 id="github-repo-page" tabindex="-1">GitHub repo page <a class="header-anchor" href="#github-repo-page" aria-label="Permalink to &quot;GitHub repo page&quot;">​</a></h3><p>cache ~ per repo info (your repo activity), 5min TTL. cache ready push back update invalidates + invalidate on push (webhooks 写 post-cache + push invalidation stack).</p><hr><h2 id="九、capacity-planning" tabindex="-1">九、Capacity Planning <a class="header-anchor" href="#九、capacity-planning" aria-label="Permalink to &quot;九、Capacity Planning&quot;">​</a></h2><p>Cache size = working_set × budget_factor.</p><ul><li>working_set = active users / active items你需要 cache.</li><li>budget_factor = 1.5 for 实际 write+read膨胀 not real working set.</li></ul><p>Once growth exceeded cache size, evictions spike and hit_ratio drops abruptly.</p><h3 id="monitoring-metrics" tabindex="-1">Monitoring Metrics <a class="header-anchor" href="#monitoring-metrics" aria-label="Permalink to &quot;Monitoring Metrics&quot;">​</a></h3><ul><li><code>eviction_rate</code> — memory pressure</li><li><code>hit_ratio</code> per cache tier</li><li><code>latency_p99</code> per cache tier</li></ul><hr><h2 id="十、典型事故" tabindex="-1">十、典型事故 <a class="header-anchor" href="#十、典型事故" aria-label="Permalink to &quot;十、典型事故&quot;">​</a></h2><h3 id="twitter-2012-cache-failure-storm" tabindex="-1">Twitter 2012 cache failure storm <a class="header-anchor" href="#twitter-2012-cache-failure-storm" aria-label="Permalink to &quot;Twitter 2012 cache failure storm&quot;">​</a></h3><p>并没有 hot Twitter multipagecache size. Cache cluster auto 重启一次性失败 evicted all hot keys, 缓存miss → backend load倍 10×. Backpressure blocked cache fill from origin. Fix: gradual Redis cluster 加 extended TTL.</p><h3 id="github-pages-cache-invalidation" tabindex="-1">GitHub Pages cache invalidation <a class="header-anchor" href="#github-pages-cache-invalidation" aria-label="Permalink to &quot;GitHub Pages cache invalidation&quot;">​</a></h3><p>GitHub 失不复 User Warehouse role 触 valid cache headers in past and als (actually legitimately re-attached) user repo access SSH pull before cache key. 缓存pre-shipment dict-configuration with Redis 配- hit旧 issue maintenance. cache-r地段 fixed.</p><h3 id="facebook-memcached-thundering-herd" tabindex="-1">Facebook Memcached Thundering Herd <a class="header-anchor" href="#facebook-memcached-thundering-herd" aria-label="Permalink to &quot;Facebook Memcached Thundering Herd&quot;">​</a></h3><p>Facebook beam cache miss for single key contributions spawn deployment caches of same values = 1000 parallel computations of value. Fix: Token lease每 cache key, single 是 worker process recompute other wait.</p><hr><h2 id="十一、易错清单" tabindex="-1">十一、易错清单 <a class="header-anchor" href="#十一、易错清单" aria-label="Permalink to &quot;十一、易错清单&quot;">​</a></h2><ol><li><strong>Cache 大不等于 hit ratio 大</strong>: hit ratio 与 working_set 大小 ratio + 失效策略 + sequence access patterns 息息相关.</li><li><strong>不要把所有 keys 都放 in-process LRU+过期多</strong>: memory size 8% of 进程 max is h大. Eviction spikes if abuse</li><li><strong>In-process cache + multi-instance issue: multi-replica divergent cache</strong> — must include coherence layer (pub-sub to invalidate).</li><li><strong>Cache miss for large file triggers thundering herd</strong> (multiple request simultaneously computing same value): Solutions: lock-and-fetch single worker pattern or use stale-while-revalidate.</li><li><strong>Redis Cluster size 5 nodes minimum for production HA</strong>: lower than 3 primary 3 replicas (6 total) 风险 RPO &gt; 0 after async replication lag.</li><li><strong>不要 cache &quot;hot row&quot; with infinite TTL</strong>: hot content changes 偶尔变 so cache stale 会被 client 不要 把 always fresh extract e.g. always to fetch stored in raw.</li></ol><hr><h2 id="十二、这一章带走的东西" tabindex="-1">十二、这一章带走的东西 <a class="header-anchor" href="#十二、这一章带走的东西" aria-label="Permalink to &quot;十二、这一章带走的东西&quot;">​</a></h2><ol><li>Multi-level cache stack: CPU L1/L2/L3 → OS Page Cache → in-process (Caffeine) → Redis → Remote CDN → origin.</li><li>In-process cache 通常 LRU/Window-TinyLFU eviction; remote cache 通常 Redis single cluster + cluster replicate 写写入写异步.</li><li>CDN 缓存 hot static (images, fonts, video); edge POP 直接服务 user, 缓 backend 80-99% load.</li><li>Cache hit ratio exponential: ✅; 99% hit 比 95% hit 后端 load 减 5×, 99.9% 减 50× more. e. doubling a hit ratio reduces backend load by near factor.</li><li>Thundering herd: multiple 同时 miss = thundering herd; 同 1 worker fetch + others wait 应避免.</li></ol><hr><p>下一节 → <a href="./patterns">缓存模式</a></p>`,115)])])}const u=e(n,[["render",r]]);export{m as __pageData,u as default};
